from pathlib import Path
import pandas as pd,numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(__file__).resolve().parent;d=pd.read_csv(R/'cluster_annotations.csv',dtype={'cluster':str});e=pd.read_csv(R/'cluster_marker_evidence.csv',dtype={'cluster':str});genes=list(dict.fromkeys('/'.join(d.subtype_EN.str.split().str[0]).split('/')));groups=d.cluster.tolist();means=e.pivot(index='cluster',columns='gene',values='mean_log1p_CP10k').reindex(index=groups,columns=genes);fra=e.pivot(index='cluster',columns='gene',values='fraction').reindex(index=groups,columns=genes);assert means.notna().all().all();scaled=means/means.max(axis=0).replace(0,1);fig,ax=plt.subplots(figsize=(18,10));xx,yy=np.meshgrid(range(len(genes)),range(len(groups)));pts=ax.scatter(xx.ravel(),yy.ravel(),s=fra.to_numpy().ravel()*110,c=scaled.to_numpy().ravel(),cmap='Reds',vmin=0,vmax=1,edgecolors='#999999',linewidths=.2);ax.set_xticks(range(len(genes)),genes,rotation=90,fontsize=9);ax.set_yticks(range(len(groups)),d.cluster_label,fontsize=9);ax.invert_yaxis();ax.set_xlim(-.8,len(genes)-.2);ax.set_title('Named RNA states | size: detected fraction | color: per-gene scaled mean');fig.colorbar(pts,ax=ax,shrink=.55,label='Scaled mean log1p(CP10k)');fig.tight_layout();fig.savefig(R/'named_cluster_marker_dotplot.png',dpi=180);fig.savefig(R/'named_cluster_marker_dotplot.pdf');plt.close(fig);print('Named marker figure complete')
